def test_example1():
    solution = Solution()
    recipes = ["bread"]
    ingredients = [["yeast", "flour"]]
    supplies = ["yeast", "flour", "corn"]
    result = solution.findAllRecipes(recipes, ingredients, supplies)
    assert result == ["bread"]


def test_example2():
    solution = Solution()
    recipes = ["bread", "sandwich"]
    ingredients = [["yeast", "flour"], ["bread", "meat"]]
    supplies = ["yeast", "flour", "meat"]
    result = solution.findAllRecipes(recipes, ingredients, supplies)
    assert set(result) == {"bread", "sandwich"}


def test_example3():
    solution = Solution()
    recipes = ["bread", "sandwich", "burger"]
    ingredients = [["yeast", "flour"], ["bread", "meat"], ["sandwich", "meat", "bread"]]
    supplies = ["yeast", "flour", "meat"]
    result = solution.findAllRecipes(recipes, ingredients, supplies)
    assert set(result) == {"bread", "sandwich", "burger"}


def test_no_recipes_possible():
    solution = Solution()
    recipes = ["bread"]
    ingredients = [["yeast", "flour"]]
    supplies = ["yeast"]
    result = solution.findAllRecipes(recipes, ingredients, supplies)
    assert result == []


def test_single_recipe_already_supplied():
    solution = Solution()
    recipes = ["cake"]
    ingredients = [["butter", "sugar"]]
    supplies = ["butter", "sugar", "eggs"]
    result = solution.findAllRecipes(recipes, ingredients, supplies)
    assert result == ["cake"]


def test_circular_dependency_with_supplies():
    solution = Solution()
    recipes = ["a", "b"]
    ingredients = [["b"], ["a"]]
    supplies = ["flour"]
    result = solution.findAllRecipes(recipes, ingredients, supplies)
    assert result == []


def test_complex_chain():
    solution = Solution()
    recipes = ["recipe1", "recipe2", "recipe3"]
    ingredients = [["flour", "water"], ["recipe1", "eggs"], ["recipe2", "milk"]]
    supplies = ["flour", "water", "eggs", "milk"]
    result = solution.findAllRecipes(recipes, ingredients, supplies)
    assert set(result) == {"recipe1", "recipe2", "recipe3"}


